private static int digitsSum(long n) {
    int neg = 1;
    if (n < 0) {
        n = -n;
        neg = -1;
    }
    List<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add((int) (n % 10));
        n /= 10;
    }
    digits.set(0, digits.get(0) * neg);
    return digits.stream().mapToInt(Integer::intValue).sum();
}

