fn digits_sum(mut n: isize) -> isize {
    let neg = if n < 0 { -1 } else { 1 };
    n = n.abs();
    let digits: Vec<isize> = n.to_string().chars().map(|c| c.to_digit(10).unwrap() as isize).collect();
