public static List<long> SortEven(List<long> l) {
    var evens = l.Select((value, index) => new { Value = value, Index = index })
                 .Where(x => x.Index % 2 == 0)
                 .Select(x => x.Value)
                 .ToList();
    var odds = l.Select((value, index) => new { Value = value, Index = index })
                .Where(x => x.Index % 2 != 0)
                .Select(x => x.Value)
                .ToList();
    evens.Sort();
    var ans = new List<long>();

    for (int i = 0; i < Math.Min(evens.Count, odds.Count); i++) {
        ans.Add(evens[i]);
        ans.Add(odds[i]);
    }

    if (evens.Count > odds.Count) {
        ans.Add(evens.Last());
    }

    return ans;
}

