            if index == '.' || index == '!' || index == '?' {
                if let (Some(next_index), Some(after_next_index), Some(third_after_index)) = (
                    S.chars().nth(i + 1),
                    S.chars().nth(i + 2),
                    S.chars().nth(i + 3),
                ) {
                    if next_index == ' ' && after_next_index == 'I' && third_after_index == ' ' {
                        t += 1;
                    }
                }
            }
        }
    }
    t
}

