std::tuple<long, long> even_odd_palindrome(long n) {

    auto isPalindrome = [](long number) -> bool {
        std::string str = std::to_string(number);
        std::string reversedStr = str;
        std::reverse(reversedStr.begin(), reversedStr.end());
        return str == reversedStr;
    };

    long evenPalindromeCount = 0;
    long oddPalindromeCount = 0;

    for (long i = 1; i <= n; ++i) {
        if (i % 2 == 1 && isPalindrome(i)) {
            oddPalindromeCount += 1;
        } else if (i % 2 == 0 && isPalindrome(i)) {
            evenPalindromeCount += 1;
        }
    }

    return std::make_tuple(evenPalindromeCount, oddPalindromeCount);
}

bool correct_bracketing(std::string brackets) {
    int depth = 0;
    for (char b : brackets) {
        if (b == '(') {
            depth += 1;
        } else {
            depth -= 1;
        }
        if (depth < 0) {
            return false;
        }
    }
    return depth == 0;
}

