bool is_multiply_prime(long a) {
    for (int i = 2; i <= 100; ++i) {
        if (!is_prime(i)) {
            continue;
        }
        for (int j = 2; j <= 100; ++j) {
            if (!is_prime(j)) {
                continue;
            }
            for (int k = 2; k <= 100; ++k) {
                if (!is_prime(k)) {
