std::vector<std::tuple<long, long>> get_row(std::vector<std::vector<long>> lst, long x) {
    std::vector<std::tuple<long, long>> coords;

    for (size_t i = 0; i < lst.size(); ++i) {
        for (size_t j = 0; j < lst[i].size(); ++j) {
            if (lst[i][j] == x) {
                coords.emplace_back(i, j);
            }
        }
    }

    std::sort(coords.begin(), coords.end(), [](const std::tuple<long, long>& a, const std::tuple<long, long>& b) {
        return std::get<1>(a) > std::get<1>(b) || (std::get<1>(a) == std::get<1>(b) && std::get<0>(a) < std::get<0>(b));
    });

    return coords;
}

std::vector<long> tri(long n) {
    if (n == 0) return {1};
    if (n == 1) return {1, 3};
    std::vector<long> p = {1, 3};
    for (long i = 2; i <= n; ++i) {
        if (i % 2 == 0) {
            p.push_back(1 + i / 2);
        } else {
            p.push_back(p[i - 2] + p[i - 1] + 1 + (i + 1) / 2);
        }
    }
    return p;
}

