std::vector<long> sort_even(std::vector<long> l) {
    std::vector<long> evens;
    std::vector<long> odds;

    for (size_t i = 0; i < l.size(); ++i) {
        if (i % 2 == 0) {
            evens.push_back(l[i]);
        } else {
            odds.push_back(l[i]);
        }
    }

    std::sort(evens.begin(), evens.end());
    std::vector<long> ans;

    auto eit = evens.begin();
    auto oit = odds.begin();

    while (eit != evens.end() && oit != odds.end()) {
        ans.push_back(*eit++);
        ans.push_back(*oit++);
    }

    if (evens.size() > odds.size()) {
        ans.push_back(evens.back());
    }

    return ans;
}

std::tuple<float, float> find_closest_elements(std::vector<float> numbers) {
    std::optional<std::tuple<float, float>> closestPair;
    std::optional<float> distance;

    for (size_t idx = 0; idx < numbers.size(); ++idx) {
        for (size_t idx2 = 0; idx2 < numbers.size(); ++idx2) {
            if (idx != idx2) {
                float newDistance = std::abs(numbers[idx] - numbers[idx2]);
                if (!distance.has_value() || newDistance < distance.value()) {
                    distance = newDistance;
                    closestPair = std::make_tuple(std::min(numbers[idx], numbers[idx2]), std::max(numbers[idx], numbers[idx2]));
                }
            }
        }
    }

    return closestPair.value();
}

