bool is_nested(std::string string) {
    std::vector<int> openingBracketIndex;
    std::vector<int> closingBracketIndex;

    for (size_t i = 0; i < string.length(); ++i) {
        if (string[i] == '[') {
            openingBracketIndex.push_back(i);
        } else {
            closingBracketIndex.push_back(i);
        }
    }

    std::reverse(closingBracketIndex.begin(), closingBracketIndex.end());
    int cnt = 0;
    int i = 0;
    size_t l = closingBracketIndex.size();

    for (int idx : openingBracketIndex) {
        if (i < l && idx < closingBracketIndex[i]) {
            cnt += 1;
            i += 1;
        }
    }

    return cnt >= 2;
}

std::vector<long> order_by_points(std::vector<long> nums) {

    auto digitsSum = [](long n) -> long {
        int neg = 1;
        long number = n;
        if (n < 0) {
            number = -n;
            neg = -1;
        }
        std::string strNum = std::to_string(number);
        std::vector<int> digits;
        for (char c : strNum) {
            digits.push_back(c - '0');
        }
        digits[0] *= neg;
        return std::accumulate(digits.begin(), digits.end(), 0L);
    };

    std::sort(nums.begin(), nums.end(), [&](long a, long b) {
        return digitsSum(a) < digitsSum(b);
    });

    return nums;
}

