std::string circular_shift(long x, long shift) {
    std::string s = std::to_string(x);
    if (shift > s.length()) {
        std::reverse(s.begin(), s.end());
        return s;
    } else {
        size_t index = s.length() - shift;
        return s.substr(index) + s.substr(0, index);
    }
}

std::vector<long> pluck(std::vector<long> arr) {
    if (arr.empty()) {
        return {};
    }

    std::vector<long> evens;
    for (long num : arr) {
        if (num % 2 == 0) {
            evens.push_back(num);
        }
    }

    if (evens.empty()) {
        return {};
    }

    auto minEven = *std::min_element(evens.begin(), evens.end());
    auto it = std::find(arr.begin(), arr.end(), minEven);
    if (it != arr.end()) {
        return {minEven, std::distance(arr.begin(), it)};
    }

    return {};
}

