std::string get_closest_vowel(std::string word) {
    if (word.length() < 3) {
        return "";
    }

    std::set<char> vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'O', 'U', 'I'};

    for (int i = word.length() - 2; i >= 1; --i) {
        if (vowels.find(word[i]) != vowels.end()) {
            char prevChar = word[i - 1];
            char nextChar = word[i + 1];

            if (vowels.find(prevChar) == vowels.end() && vowels.find(nextChar) == vowels.end()) {
                return std::string(1, word[i]);
            }
        }
    }

    return "";
}

std::vector<long> sort_array(std::vector<long> array) {
